arguments.command:
$root = "$env:USERPROFILE\.copilot\session-state"
$dirs = @(Get-ChildItem $root -Directory -ErrorAction SilentlyContinue)
"session-state dirs: $($dirs.Count)"
$big = @(); $small = @(); $hits = @(); $nolog = @()
foreach ($s in $dirs) {
  $f = Join-Path $s.FullName 'events.jsonl'
  if (Test-Path $f) {
    $len = (Get-Item $f).Length
    $first = Get-Content $f -TotalCount 1
    $start = if ($first -match '"startTime":"([^"]+)"') { $Matches[1] } else { '?' }
    if ($len -gt 20000) {
      $row = "$($s.Name) | $start | $len bytes"
      $big += $row
      if (Select-String -Path $f -Pattern 'Korytos|Merlin|Praison|Preyson|Praision' -Quiet) { $hits += $row }
    } else {
      $small += "$($s.Name) | $start | $len bytes"
    }
  } else { $nolog += $s.Name }
}
"BIG SESSIONS (>20KB): $($big.Count)"
"--- SIGIL MATCHES (candidates) ---"
$hits
"--- OTHER BIG SESSIONS (no sigil) ---"
$big | Where-Object { $hits -notcontains $_ }
