$small
"--- DIRS WITHOUT events.jsonl ---"
$nolog
"--- FOLDER STRUCTURE OF CANDIDATES (names only) ---"
foreach ($h in $hits) {
  $n = ($h -split ' \| ')[0]
  "[$n]"
  $items = Get-ChildItem (Join-Path $root $n) -Force -ErrorAction SilentlyContinue
